export function drawPalms(ctx, w, h, grade, seed) {
  if (!ctx || !(w > 0) || !(h > 0)) return;

  const color = (grade && grade.dark) || GRADES.vice.dark;
  const rand = mulberry32(seed);
  const trees = 3 + Math.floor(rand() * 3);

  ctx.save();
  for (let i = 0; i < trees; i++) {
