    drawRays(ctx, w, h, band, accent);
  } else if (kind === 'dots') {
    drawDots(ctx, w, bandTop, band, ink);
  } else if (kind === 'grid') {
    drawGrid(ctx, w, bandTop, band, ink);
  }

  ctx.restore();
}
