  transition: transform 0.16s ease, box-shadow 0.16s ease, border-color 0.16s ease;
}

.thumb:hover {
  transform: translateY(-2px);
  border-color: var(--magenta-soft);
}

.thumb.is-active {
  border-color: var(--magenta);
  box-shadow: 0 0 0 2px var(--magenta), 0 0 18px rgba(255, 45, 149, 0.55);
}

.thumb-index {
  position: absolute;
  left: 4px;
  bottom: 4px;
  padding: 1px 5px;
  font-family: var(--font-label);
  font-size: 12px;
  letter-spacing: 0.08em;
  color: var(--ink);
  background: rgba(10, 5, 18, 0.78);
  border-radius: 3px;
}

/* ---------- Fields ---------- */

.field + .field,
.field-field-pair + .field {
  margin-top: 12px;
}

.field-field-pair {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin-top: 12px;
}

.field-field-pair .field + .field {
  margin-top: 0;
}

.field-label {
  display: block;
  margin-bottom: 5px;
  font-family: var(--font-label);
  font-size: 15px;
  line-height: 1.1;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--ink-soft);
}

.text-input,
.select-input {
  width: 100%;
  min-width: 0;
  padding: 9px 10px;
  font-family: var(--font-ui);
  font-size: 13px;
  color: var(--ink);
  background: #0e0719;
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  transition: border-color 0.16s ease, box-shadow 0.16s ease;
}

.text-input:hover,
.select-input:hover {
  border-color: #59357d;
}

.text-input:focus,
.select-input:focus {
  outline: none;
  border-color: var(--magenta);
  box-shadow: 0 0 0 3px rgba(255, 45, 149, 0.14);
}

.select-input {
  appearance: none;
  padding-right: 28px;
  background-image:
    linear-gradient(45deg, transparent 50%, var(--magenta-soft) 50%),
    linear-gradient(135deg, var(--magenta-soft) 50%, transparent 50%);
  background-position:
    calc(100% - 16px) calc(50% + 1px),
    calc(100% - 11px) calc(50% + 1px);
  background-size: 5px 5px, 5px 5px;
  background-repeat: no-repeat;
  cursor: pointer;
}

.select-input option {
  background: #150c24;
  color: var(--ink);
}

/* ---------- Range & checks ---------- */

.range-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
}

.range-value {
  font-family: var(--font-label);
  font-size: 14px;
  letter-spacing: 0.08em;
  color: var(--orange);
}

.range-input {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 5px;
  margin: 9px 0 4px;
  border-radius: 99px;
  background: linear-gradient(90deg, var(--magenta), var(--orange));
  cursor: pointer;
}

.range-input::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 17px;
  height: 17px;
  border-radius: 50%;
  background: var(--ink);
  border: 3px solid var(--magenta);
  box-shadow: 0 0 12px rgba(255, 45, 149, 0.7);
}

.range-input::-moz-range-thumb {
  width: 13px;
  height: 13px;
  border-radius: 50%;
  background: var(--ink);
  border: 3px solid var(--magenta);
  box-shadow: 0 0 12px rgba(255, 45, 149, 0.7);
}

.check-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 16px;
  margin-top: 14px;
}

.check-label {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  cursor: pointer;
  font-family: var(--font-label);
  font-size: 15px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--ink-soft);
}

.check-label:hover {
  color: var(--ink);
}

.check-input {
  width: 16px;
  height: 16px;
  margin: 0;
  accent-color: var(--magenta);
  cursor: pointer;
}

/* ---------- Compact screens ---------- */

@media (max-width: 1100px) {
  .topbar {
    flex-wrap: wrap;
    height: auto;
    flex-basis: auto;
    padding: 12px 16px;
  }

  .brand-subtitle {
    white-space: normal;
  }

  .sidebar {
    flex-basis: 290px;
    width: 290px;
  }
}
